/**
 * Microsoft Teams Node - Version 2
 * Discriminator: resource=onlineMeeting, operation=createOrGet
 */


interface Credentials {
  microsoftTeamsOAuth2Api: CredentialReference;
  microsoftOAuth2Api: CredentialReference;
  microsoftEntraServicePrincipalApi: CredentialReference;
}

/** Create an online meeting with your own external ID, or get the existing meeting with that ID */
export type MicrosoftTeamsV2OnlineMeetingCreateOrGetParams = {
  resource: 'onlineMeeting';
  operation: 'createOrGet';
  authentication?: 'microsoftTeamsOAuth2Api' | 'microsoftOAuth2Api' | 'microsoftEntraServicePrincipalApi';
/**
 * The user whose meetings the app creates and manages. From List and user principal names need the User.Read.All application permission; an object ID needs none.
 * @searchListMethod getUsers
 * @displayOptions.show { /authentication: ["microsoftEntraServicePrincipalApi"] }
 * @default {"mode":"list","value":""}
 */
    organizerId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
/**
 * Your own ID for the meeting. Running the node again with the same ID for the same organizer returns the existing meeting instead of creating another one.
 */
    externalId: string | Expression<string>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** The people to invite to the meeting. Attendees apply only when a new meeting is created. The node still looks up every attendee on every run.
     * @default {}
     */
    attendees?: {
        /** Attendee
     */
    attendee?: Array<{
      /** Select the user from the list or by ID. Guest users must be given by their object ID, not by their user principal name. Attendees apply only when a new meeting is created. The node still looks up every attendee on every run.
       * @searchListMethod getUsers
       * @default {"mode":"list","value":""}
       */
      userId?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
    }>;
  };
    /** The date and time when the meeting ends. Must be later than Start Time, which must also be set. If left out, the meeting lasts one hour.
     */
    endDateTime?: string | Expression<string>;
    /** The date and time when the meeting starts. Defaults to now.
     */
    startDateTime?: string | Expression<string>;
    /** The subject of the meeting
     */
    subject?: string | Expression<string>;
  };
};

export type MicrosoftTeamsV2OnlineMeetingCreateOrGetNode = {
  type: 'n8n-nodes-base.microsoftTeams';
  version: 2;
  config: NodeConfig<MicrosoftTeamsV2OnlineMeetingCreateOrGetParams> & { credentials?: Credentials };
};